#include <stdio.h>
#include <stdlib.h>

// Define the grid size
#define GRID_SIZE 6

// Define the grid, visited, and distance arrays
char grid[GRID_SIZE][GRID_SIZE];
int visited[GRID_SIZE][GRID_SIZE];
int dist[GRID_SIZE][GRID_SIZE];

// Define the queue arrays
int q_row[GRID_SIZE * GRID_SIZE];
int q_col[GRID_SIZE * GRID_SIZE];

int main(int argc, char **argv) {
    // Initialize the grid, visited, and distance arrays
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < GRID_SIZE; j++) {
            grid[i][j] = argv[1][i * GRID_SIZE + j];
            visited[i][j] = 0;
            dist[i][j] = -1;
        }
    }

    // Initialize the queue
    int q_size = 0;
    int start_row = atoi(argv[2]);
    int start_col = atoi(argv[3]);
    q_row[q_size] = start_row;
    q_col[q_size] = start_col;
    visited[start_row][start_col] = 1;
    dist[start_row][start_col] = 0;
    q_size++;

    // Perform BFS
    while (q_size > 0) {
        int row = q_row[0];
        int col = q_col[0];
        q_size--;
        for (int i = 0; i < 4; i++) {
            int new_row = row + (i == 0 ? -1 : (i == 1 ? 1 : 0));
            int new_col = col + (i == 2 ? -1 : (i == 3 ? 1 : 0));
            if (new_row >= 0 && new_row < GRID_SIZE && new_col >= 0 && new_col < GRID_SIZE && grid[new_row][new_col] != '#' && !visited[new_row][new_col]) {
                visited[new_row][new_col] = 1;
                dist[new_row][new_col] = dist[row][col] + 1;
                q_row[q_size] = new_row;
                q_col[q_size] = new_col;
                q_size++;
            }
        }
    }

    // Print the distance to each cell
    for (int i = 0; i < GRID_SIZE; i++) {
        for (int j = 0; j < GRID_SIZE; j++) {
            if (dist[i][j] != -1) {
                printf("dist=%d\n", dist[i][j]);
            } else {
                printf("UNREACHABLE\n");
            }
        }
    }

    return 0;
}
